export const byPath = new Map(ROUTES.map((r) => [r.path, r]));

export function routeFor(slug: string[] | undefined): SiteRoute | undefined {
  const p = !slug || slug.length === 0 ? "/" : "/" + slug.map(decodeURIComponent).join("/") + "/";
  return byPath.get(p);
}
